Student s1 = new Student();
Student s2 = new Student();

System.out.println(s1.equals(s2));
// false

class Student {
    int id;

    Student(int id){
        this.id = id;
    }

    @Override
    public boolean equals(Object obj){
        Student s = (Student)obj;
        return this.id == s.id;
    }
}

@Override
public boolean equals(Object obj){
    Student s = (Student)obj;
    return id == s.id;
}

@Override
public int hashCode(){
    return Integer.hashCode(id);
}
